function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open('lume-studio-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('vault');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function readRecord(k=mode){return new Promise((res,rej)=>{let r=db.transaction('vault').objectStore('vault').get(k);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
