async function commit(fn,action='Alteração salva'){if(busy)throw Error('Aguarde a operação atual.');busy=true;try{const next=structuredClone(state);fn(next);next.audit.push({id:uid(),at:new Date().toISOString(),action});next.audit=next.audit.slice(-200);validate(next);const out=await encode(next);const rev=await persist(out,revision);state=next;revision=rev;record={...out,rev};render();return true}finally{busy=false}}
function validate(d){if(d&&!d.quotes)d.quotes=[];if(d&&!d.contracts)d.contracts=[];if(!d||d.app!=='LumeStudio'||d.schema!==1||!d.profile||typeof d.profile.name!=='string')throw Error('Backup incompatível com LENS CORE STUDIO.');for(const c of ['clients','projects','events','transactions','gear','audit']){if(!Array.isArray(d[c])||d[c].length>30000)throw Error('Coleção inválida: '+c);const ids=new Set();for(const x of d[c]){if(!x||typeof x.id!=='string'||!/^[\w-]{1,100}$/.test(x.id)||ids.has(x.id))throw Error('Identificador inválido ou duplicado.');ids.add(x.id)}}for(const k of ['name','owner','phone','email','city'])if(typeof d.profile[k]!=='string')throw Error('Perfil inválido.');
for(const [list,fields] of [['clients',['name','phone','email','type','source','notes']],['projects',['name','type','stage','date','due','location','brief','notes']],['events',['title','start','end','type','location','notes']],['transactions',['description','date','type']],['gear',['name','category','model','serial','status','notes']]])for(const x of d[list])for(const k of fields)if(typeof x[k]!=='string'||x[k].length>100000)throw Error('Campo inválido: '+k);
const dateOK=x=>!x||(/^\d{4}-\d{2}-\d{2}$/.test(x)&&Number.isFinite(Date.parse(x+'T12:00:00'))&&localDate(new Date(x+'T12:00:00'))===x);
for(const p of d.projects){if(!dateOK(p.date)||!dateOK(p.due))throw Error('Data inválida.');for(const list of [p.checks,p.deliveries]){if(!Array.isArray(list))throw Error('Itens inválidos.');const ids=new Set();for(const x of list){if(!x||typeof x.id!=='string'||!/^[-\w]{1,100}$/.test(x.id)||ids.has(x.id))throw Error('Identificador de item inválido.');ids.add(x.id)}}for(const x of p.deliveries)if(!dateOK(x.due)||typeof x.url!=='string')throw Error('Entrega inválida.');}
const imageOK=x=>!x||(typeof x==='string'&&x.length<3000000&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(x));if(!imageOK(d.profile.logo))throw Error('Logo inválido.');for(const p of d.projects)if(!imageOK(p.cover))throw Error('Capa inválida.');if(!Array.isArray(d.contracts))throw Error('Contratos inválidos.');const cids=new Set();for(const c of d.contracts){if(!c||typeof c.id!=='string'||!/^[-\w]{1,100}$/.test(c.id)||cids.has(c.id)||typeof c.title!=='string'||typeof c.text!=='string'||!d.clients.some(x=>x.id===c.clientId))throw Error('Contrato inválido.');cids.add(c.id);}if(!Array.isArray(d.quotes))throw Error('Propostas inválidas.');const qids=new Set();for(const q of d.quotes){if(!q||typeof q.id!=='string'||!/^[-\w]{1,100}$/.test(q.id)||qids.has(q.id)||typeof q.title!=='string'||typeof q.scope!=='string'||typeof q.validUntil!=='string'||!['Rascunho','Enviada','Aceita','Recusada'].includes(q.status)||!Number.isSafeInteger(q.amount)||q.amount<0||!d.clients.some(c=>c.id===q.clientId)||(q.projectId&&!d.projects.some(p=>p.id===q.projectId)))throw Error('Proposta inválida.');qids.add(q.id);}const clientIds=new Set(d.clients.map(x=>x.id)),projectIds=new Set(d.projects.map(x=>x.id));for(const c of d.clients)if(typeof c.name!=='string'||!c.name.trim())throw Error('Cliente sem nome.');for(const p of d.projects){if(!clientIds.has(p.clientId)||typeof p.name!=='string'||!stages.includes(p.stage)||!Number.isSafeInteger(p.value)||p.value<0||!Array.isArray(p.checks)||!Array.isArray(p.deliveries))throw Error('Trabalho inválido ou cliente ausente.');for(const c of p.checks)if(typeof c.id!=='string'||typeof c.text!=='string'||typeof c.done!=='boolean')throw Error('Checklist inválido.');for(const x of p.deliveries)if(typeof x.id!=='string'||typeof x.name!=='string'||!['Pendente','Em produção','Aguardando aprovação','Entregue'].includes(x.status)||!validURL(x.url))throw Error('Entrega inválida.');}for(const e of d.events){if(e.projectId&&!projectIds.has(e.projectId)||!Number.isFinite(Date.parse(e.start))||!Number.isFinite(Date.parse(e.end))||e.end<=e.start)throw Error('Compromisso inválido.')}for(const t of d.transactions)if((t.projectId&&!projectIds.has(t.projectId))||!['Recebimento','Despesa','Estorno'].includes(t.type)||!Number.isSafeInteger(t.amount)||t.amount<=0||!/^\d{4}-\d{2}-\d{2}$/.test(t.date))throw Error('Lançamento inválido.');for(const pid of projectIds){const net=d.transactions.filter(x=>x.projectId===pid).reduce((a,x)=>a+(x.type==='Recebimento'?x.amount:x.type==='Estorno'?-x.amount:0),0);if(net<0)throw Error('Os estornos não podem superar os recebimentos do trabalho.');}return d}
const validURL=u=>!u||(/^https?:\/\//i.test(u)&&(()=>{try{return !!new URL(u).hostname}catch{return false}})());
const client=id=>state.clients.find(x=>x.id===id), project=id=>state.projects.find(x=>x.id===id), initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
function totals(pid){let a=state.transactions.filter(x=>!pid||x.projectId===pid),paid=a.reduce((s,x)=>s+(x.type==='Recebimento'?x.amount:x.type==='Estorno'?-x.amount:0),0),cost=a.filter(x=>x.type==='Despesa').reduce((s,x)=>s+x.amount,0);return {paid,cost,cash:paid-cost}}
const active=p=>!['Cancelado','Arquivado'].includes(p.stage),picture=p=>p.type==='Vídeo'?img.video:p.type==='Foto + Vídeo'?img.magic:img.photo;
function btn(label,action,ico='',cls=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${!label?'aria-label="Mostrar ou ocultar senha"':''}>${ico?icon(ico):''}${label}</button>`}
function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function area(label,name,value='',extra=''){return `<label class="full">${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`}
function select(label,name,values,value='',extra=''){return `<label>${label}<select name="${name}" ${extra}>${values.map(v=>{let [id,text]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`}).join('')}</select></label>`}
function badge(stage){return `<span class="badge ${['Entregue','Entrega','Disponível','Confirmado'].includes(stage)?'green':['Cancelado','Manutenção'].includes(stage)?'red':stage==='Pós-produção'?'blue':''}">${esc(stage)}</span>`}
function header(title,sub,button=''){return `<div class="heading between"><div><h1>${title}</h1><p>${sub}</p></div>${button}</div>`}
function empty(title,sub,action='',label='Adicionar'){return `<div class="empty">${icon('folder')}<h3>${title}</h3><p>${sub}</p>${action?btn(label,action,'plus','primary'):''}</div>`}
function modal(title,body,submit=null,label='Salvar'){dirty=false;const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${submit?`<form id="form" data-kind="${submit}">`:''}${body}<div id="form-error" class="form-error" role="alert"></div>${submit?`<div class="modal-footer">${btn('Cancelar','close')}<button class="btn primary" type="submit">${label}</button></div></form>`:''}</div>`;if(!d.open)d.showModal();setTimeout(()=>d.querySelector('input:not([type=hidden]),select,textarea')?.focus(),60)}
function closeModal(force=false){if(!force&&dirty&&!confirm('Descartar as alterações não salvas?'))return;$('#modal').close();dirty=false;}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800)}
function go(r,id=null){route=r;selected=id;tab='Resumo';query='';filter='';render();window.scrollTo(0,0)}
function shell(content){const current=route==='project'||route==='session'?'projects':route;return `<aside class="sidebar"><div class="brand"><div class="brand-mark"></div><div><strong>LUME</strong><small>STUDIO</small></div></div><div class="nav-label">SEU ESTÚDIO</div>${navs.slice(0,5).map(([r,t,i])=>`<button class="nav-item ${current===r?'active':''}" data-action="nav:${r}">${icon(i)}${t}</button>`).join('')}<div class="nav-label">NOS BASTIDORES</div>${navs.slice(5).map(([r,t,i])=>`<button class="nav-item ${current===r?'active':''}" data-action="nav:${r}">${icon(i)}${t}</button>`).join('')}<div class="side-footer"><div class="row"><div class="avatar">${esc(initials(state.profile.owner||state.profile.name))}</div><div class="grow"><b style="font-size:.8125rem;color:#dfe3dd">${esc(state.profile.owner||'Meu estúdio')}</b><small style="display:block;font-size:.6875rem;margin-top:4px">V${VERSION} · ${mode==='demo'?'Demonstração':'Neste dispositivo'}</small></div><button class="icon-btn" data-action="exit" aria-label="Sair">${icon('logout')}</button></div></div></aside><div class="workspace"><header class="topbar"><p>${esc(state.profile.name)} <span class="desktop-label"> / ${esc(navs.find(x=>x[0]===current)?.[1]||'Trabalho')}</span></p><div class="row"><span class="mode-pill">${mode==='demo'?'DADOS DE DEMONSTRAÇÃO':'SALVO NESTE DISPOSITIVO'}</span><button class="icon-btn" data-action="nav:home" aria-label="Pendências de hoje">${icon('bell')}</button><div class="avatar">${esc(initials(state.profile.owner||state.profile.name))}</div></div></header><main class="main">${content}</main></div><nav class="mobile-nav" aria-label="Navegação principal">${[...navs.slice(0,5),['more','Mais','more']].map(([r,t,i])=>`<button class="${current===r||(r==='more'&&!navs.slice(0,5).some(x=>x[0]===current))?'active':''}" data-action="nav:${r}" ${current===r?'aria-current="page"':''}>${icon(i)}${t}</button>`).join('')}</nav>`}
function welcome(){return `<div class="welcome"><div class="welcome-art"><img src="${img.photo}" alt="Câmera clássica sobre tecido"><div class="caption"><p class="eyebrow">FOTOGRAFIA & VÍDEO</p><h1>Seu olhar cria.<br>Seu estúdio flui.</h1><p>Da primeira conversa à última entrega, espaço para o que você faz de melhor.</p></div></div><div class="welcome-form"><div class="brand"><div class="brand-mark"></div><div><strong>LUME</strong><small>STUDIO</small></div></div><h2>Bem-vindo ao seu estúdio.</h2><p>Organize seus trabalhos, prepare cada sessão e acompanhe suas entregas.</p>${btn('Entrar no meu estúdio','enter:real','arrow','copper')}${btn('Explorar demonstração','enter:demo','','secondary')}<small>Seus registros ficam neste navegador e dispositivo. Faça backups em Configurações. A demonstração usa dados fictícios separados.<br><br>V${VERSION} · Seu estúdio em foco</small></div></div>`}
function workCard(p){let done=p.checks.filter(x=>x.done).length,total=p.checks.length;return `<article class="card work-card" tabindex="0" role="button" aria-label="Abrir ${esc(p.name)}" data-action="project:${p.id}"><div class="work-image"><img src="${picture(p)}" alt="" loading="lazy">${badge(p.stage)}<span class="work-type">${esc(p.type)}</span></div><div class="work-body"><h3>${esc(p.name)}</h3><p>${esc(client(p.clientId)?.name)}</p><div class="between"><small>${icon('calendar')} ${fmt(p.date)}</small><small>${done}/${total} tarefas</small></div><div class="progress"><i style="width:${total?done/total*100:0}%"></i></div><div class="work-bottom"><span>Entrega ${fmt(p.due)}</span>${icon('arrow')}</div></div></article>`}
function metric(label,value,note,ico){return `<div class="card metric"><div class="metric-top">${label}${icon(ico)}</div><strong>${value}</strong><small>${note}</small></div>`}
function homePage(){let ps=state.projects.filter(active),t=totals(),due=ps.reduce((s,p)=>s+Math.max(0,p.value-totals(p.id).paid),0),next=state.events.filter(e=>e.start>=today()).sort((a,b)=>a.start.localeCompare(b.start)),n=next.find(e=>e.type==='Sessão')||next[0],p=n?project(n.projectId):null;let pending=ps.filter(p=>p.stage==='Proposta'||p.checks.some(c=>!c.done)||p.deliveries.some(d=>d.status!=='Entregue'));return header(`Seu estúdio, em movimento.`,` ${new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}`,btn('Novo trabalho','new:project','plus','primary'))+`<div class="grid cols4">${metric('Trabalhos ativos',ps.length,'Em todas as etapas','folder')}${metric('Entregas em 7 dias',ps.flatMap(p=>p.deliveries).filter(x=>x.status!=='Entregue'&&x.due&&x.due<=addDays(7)&&x.due>=today()).length,'Entregáveis pendentes','clock')}${metric('Saldo a receber',money(due),'Trabalhos ativos · total','wallet')}${metric('Saldo de caixa',money(t.cash),'Entradas − saídas · todo o período','chart')}</div><div class="grid cols2 section"><section class="hero-session"><div class="hero-copy"><div class="eyebrow">${n?'PRÓXIMO COMPROMISSO':'SEU PRÓXIMO CAPÍTULO'}</div><h2>${esc(n?.title||'Tudo começa com uma boa história.')}</h2><p>${n?fmt(n.start.slice(0,10))+' · '+n.start.slice(11)+'<br>'+esc(n.location||'Local a definir'):'Cadastre um trabalho e prepare sua próxima sessão.'}</p>${n?btn(p?'Preparar sessão':'Ver agenda',p?'session:'+p.id:'nav:agenda','arrow','copper'):btn('Criar meu primeiro trabalho','new:project','plus','copper')}</div><img class="hero-image" src="${p?picture(p):img.magic}" alt="Câmera fotográfica"></section><section class="card"><div class="between section-title"><h2>Precisa da sua atenção</h2>${icon('bell')}</div>${pending.slice(0,3).map(p=>`<div class="task-row"><div class="task-icon">${icon(p.stage==='Proposta'?'file':'clock')}</div><div class="grow"><b>${p.stage==='Proposta'?'Retornar sobre a proposta':esc(p.checks.find(c=>!c.done)?.text||'Conferir a próxima entrega')}</b><small>${esc(p.name)}</small></div><button class="icon-btn" data-action="project:${p.id}" aria-label="Abrir trabalho">${icon('arrow')}</button></div>`).join('')||empty('Tudo em dia','As próximas ações dos trabalhos aparecerão aqui.')}</section></div><section class="section"><div class="between section-title"><h2>Histórias em produção <small> / ${ps.length}</small></h2><button class="link-btn" data-action="nav:projects">Ver todos os trabalhos →</button></div><div class="grid cols3">${ps.slice(0,3).map(workCard).join('')||`<div class="card full">${empty('Seu primeiro trabalho','Organize fotografia e vídeo em um único lugar.','new:project','Criar trabalho')}</div>`}</div></section><section class="section card"><div class="between section-title"><h2>No seu horizonte</h2><button class="link-btn" data-action="nav:agenda">Abrir agenda →</button></div>${next.slice(0,3).map(eventRow).join('')||'<p class="muted">Nenhum compromisso futuro.</p>'}</section>`}
function projectsPage(){let ps=state.projects.filter(p=>(!filter||p.type===filter)&&(p.name+' '+client(p.clientId)?.name).toLowerCase().includes(query.toLowerCase()));return header('Trabalhos','Cada história, do primeiro contato à entrega.',btn('Novo trabalho','new:project','plus','primary'))+`<div class="toolbar"><div class="search">${icon('search')}<input id="search" aria-label="Buscar trabalho" placeholder="Buscar trabalho ou cliente" value="${esc(query)}"></div><select id="filter" aria-label="Tipo de trabalho" style="width:auto"><option value="">Foto e vídeo</option>${['Fotografia','Vídeo','Foto + Vídeo'].map(x=>`<option ${filter===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="grid cols3" id="results">${ps.map(workCard).join('')||`<div class="card full">${empty('Nenhum trabalho encontrado','Crie um novo trabalho ou ajuste a busca.','new:project')}</div>`}</div>`}
function clientsPage(){const cs=state.clients.filter(c=>(c.name+' '+(c.email||'')).toLowerCase().includes(query.toLowerCase()));return header('Clientes','Conversas que se transformam em histórias.',btn('Novo cliente','new:client','plus','primary'))+`<div class="toolbar"><div class="search">${icon('search')}<input id="search" aria-label="Buscar cliente" placeholder="Buscar por nome ou e-mail" value="${esc(query)}"></div></div><div class="card" style="padding:0"><div class="table-wrap"><table class="table"><thead><tr><th>CLIENTE</th><th>CONTATO</th><th>TRABALHOS</th><th>ORIGEM</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr><td><div class="row"><div class="avatar">${esc(initials(c.name))}</div><div><span class="name">${esc(c.name)}</span><small>${esc(c.type)}</small></div></div></td><td>${esc(c.phone||c.email||'Não informado')}</td><td>${state.projects.filter(p=>p.clientId===c.id).length}</td><td>${esc(c.source||'—')}</td><td><button class="icon-btn" data-action="client:${c.id}" aria-label="Abrir cliente">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>${!cs.length?empty('Sua rede começa aqui','Cadastre os contatos do seu estúdio.','new:client'):''}</div>`}
function eventRow(e){return `<div class="task-row"><div class="date-tile"><strong>${e.start.slice(8,10)}</strong><small>${new Date(e.start).toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</small></div><div class="grow"><b>${esc(e.title)}</b><small>${e.start.slice(11)} – ${e.end.slice(0,10)!==e.start.slice(0,10)?fmt(e.end.slice(0,10))+' ':''}${e.end.slice(11)} · ${esc(e.location||e.type)}</small></div><button class="icon-btn" data-action="event:${e.id}" aria-label="Editar compromisso">${icon('edit')}</button></div>`}
function agendaPage(){let [y,m]=month.split('-').map(Number),first=new Date(y,m-1,1).getDay(),days=new Date(y,m,0).getDate(),events=state.events.filter(e=>e.start.slice(0,10)<=chosen&&e.end.slice(0,10)>=chosen).sort((a,b)=>a.start.localeCompare(b.start));return header('Agenda','Sessões, reuniões e espaço para editar.',btn('Novo compromisso','new:event','plus','primary'))+`<section class="card"><div class="between calendar-controls" style="margin-bottom:20px"><div class="row"><button class="icon-btn" data-action="month:-1" aria-label="Mês anterior">${icon('back')}</button><h2 style="margin:0">${new Date(y,m-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h2><button class="icon-btn" data-action="month:1" aria-label="Próximo mês">${icon('arrow')}</button></div><div class="row"><input type="month" id="month" aria-label="Selecionar mês e ano" value="${month}" style="width:180px">${btn('Hoje','today')}</div></div><div class="calendar">${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(x=>`<div class="weekday">${x}</div>`).join('')}${Array(first).fill('<div class="day off"></div>').join('')}${Array.from({length:days},(_,i)=>{const d=`${month}-${String(i+1).padStart(2,'0')}`,es=state.events.filter(e=>e.start.slice(0,10)<=d&&e.end.slice(0,10)>=d);return `<button class="day ${d===today()?'today':''} ${d===chosen?'selected':''}" data-action="day:${d}" aria-label="${fmt(d)}, ${es.length} compromissos"><span>${i+1}</span>${es.slice(0,2).map(e=>`<small>${esc(e.title)}</small>`).join('')}${es.length>2?'<small>+'+(es.length-2)+'</small>':''}</button>`}).join('')}</div><p class="legend">Os horários seguem o fuso deste dispositivo: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}.</p></section><section class="card section"><div class="between section-title"><h2>${fmt(chosen)}</h2>${btn('Adicionar','new:event','plus')}</div>${events.map(eventRow).join('')||empty('Um respiro na agenda','Nenhum compromisso neste dia.')}</section>`}
function financeRows(pid){const ts=state.transactions.filter(t=>!pid||t.projectId===pid).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="table-wrap"><table class="table"><thead><tr><th>DESCRIÇÃO</th><th>TRABALHO</th><th>DATA</th><th>VALOR</th><th></th></tr></thead><tbody>${ts.map(t=>`<tr><td><span class="name">${esc(t.description)}</span><small>${esc(t.type)}</small></td><td>${esc(project(t.projectId)?.name)}</td><td>${fmt(t.date)}</td><td class="amount ${t.type==='Recebimento'?'positive':'negative'}">${t.type==='Recebimento'?'+':'−'} ${money(t.amount)}</td><td><button class="icon-btn" data-action="transaction:${t.id}" aria-label="Editar lançamento">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>${!ts.length?empty('Nenhum lançamento','Registre os recebimentos e despesas do trabalho.'):''}`}
function financePage(){let t=totals(),value=state.projects.filter(active).reduce((s,p)=>s+p.value,0),due=state.projects.filter(active).reduce((s,p)=>s+Math.max(0,p.value-totals(p.id).paid),0);return header('Financeiro','Clareza sobre o que entra, o que sai e o que falta receber.',btn('Novo lançamento','new:transaction','plus','primary'))+`<div class="grid cols4">${metric('Recebido líquido',money(t.paid),'Recebimentos menos estornos','wallet')}${metric('Despesas pagas',money(t.cost),'Todo o período','chart')}${metric('Saldo de caixa',money(t.cash),'Todo o período · não é lucro','wallet')}${metric('Saldo a receber',money(due),'Valores de trabalhos ativos','clock')}</div><section class="card section"><div class="between section-title"><h2>Movimentações</h2>${btn('Exportar CSV','csv','download')}</div>${financeRows()}</section><section class="card section"><h2>Por trabalho</h2><div class="table-wrap"><table class="table"><thead><tr><th>TRABALHO</th><th>VALOR</th><th>RECEBIDO</th><th>SALDO</th></tr></thead><tbody>${state.projects.filter(active).map(p=>`<tr><td>${esc(p.name)}</td><td class="amount">${money(p.value)}</td><td class="amount">${money(totals(p.id).paid)}</td><td class="amount">${money(Math.max(0,p.value-totals(p.id).paid))}</td></tr>`).join('')}</tbody></table></div><p class="legend">Valores informados manualmente. Não há conciliação bancária nesta versão.</p></section>`}
function projectPage(){const p=project(selected);if(!p)return empty('Trabalho não encontrado','Volte à lista.','nav:projects','Ver trabalhos');const c=client(p.clientId),t=totals(p.id),tabs=['Resumo','Briefing','Agenda','Produção','Entregas','Financeiro'];let content='';if(tab==='Resumo')content=`<div class="grid cols2"><div class="card"><h2>O que estamos criando</h2><div class="data-list"><div><small>Cliente</small><b>${esc(c?.name)}</b></div><div><small>Local</small><b>${esc(p.location||'A definir')}</b></div><div class="grid cols2"><div><small>Data principal</small><b>${fmt(p.date)}</b></div><div><small>Prazo geral</small><b>${fmt(p.due)}</b></div></div><div><small>Observações</small><p class="note">${esc(p.notes||'Nenhuma observação.')}</p></div></div><div class="row wrap section">${btn('Editar trabalho','edit:project:'+p.id,'edit')}${btn('Proposta / impressão','quote:'+p.id,'file')}${waButton(c,p)}</div></div><div class="card"><h2>Visão financeira</h2><div class="data-list"><div class="between"><span>Valor do trabalho</span><b>${money(p.value)}</b></div><div class="between"><span>Recebido líquido</span><b class="positive">${money(t.paid)}</b></div><div class="between"><span>Saldo a receber</span><b>${money(Math.max(0,p.value-t.paid))}</b></div><div class="between"><span>Despesas pagas</span><b>${money(t.cost)}</b></div></div><p class="legend">Saldo a receber não representa lucro.</p><div class="section">${btn('Registrar lançamento','project-transaction:'+p.id,'plus','primary')}</div></div></div><div class="card section"><div class="between"><div><h2 style="margin-bottom:7px">Etapa do trabalho</h2><p class="muted" style="font-size:.875rem;margin:0">A etapa não altera pagamentos ou entregas.</p></div><select id="stage" aria-label="Etapa do trabalho" style="max-width:190px">${stages.map(s=>`<option ${s===p.stage?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="row wrap section">${btn('Duplicar como rascunho','duplicate:'+p.id,'copy')}${!state.transactions.some(t=>t.projectId===p.id)&&!state.events.some(e=>e.projectId===p.id)&&p.stage==='Consulta'?btn('Excluir rascunho','delete-project:'+p.id,'trash','danger'):btn('Arquivar','archive:'+p.id,'folder')}</div>`;
if(tab==='Briefing')content=`<div class="card"><div class="between section-title"><h2>A direção desta história</h2>${btn('Editar briefing','brief:'+p.id,'edit')}</div><p class="note">${esc(p.brief||'Registre objetivo, estilo, pessoas essenciais e orientações para a sessão.')}</p></div>`;
if(tab==='Agenda')content=`<div class="card"><div class="between section-title"><h2>Sessões e compromissos</h2>${btn('Agendar','project-event:'+p.id,'plus')}</div>${state.events.filter(e=>e.projectId===p.id).sort((a,b)=>a.start.localeCompare(b.start)).map(eventRow).join('')||empty('Prepare o encontro','Agende a sessão, a reunião ou o bloco de edição.')}</div>`;
if(tab==='Produção')content=`<div class="card"><div class="between section-title"><h2>Checklist de produção</h2>${btn('Adicionar item','check:'+p.id,'plus')}</div>${checkRows(p)}<div class="section">${btn('Abrir Modo Sessão','session:'+p.id,'camera','primary')}</div></div>`;
if(tab==='Entregas')content=`<div class="card"><div class="between section-title"><h2>Cada entrega, no seu tempo</h2>${btn('Adicionar entrega','delivery:'+p.id,'plus')}</div>${p.deliveries.map(d=>`<div class="task-row"><div class="task-icon">${icon('file')}</div><div class="grow"><b>${esc(d.name)}</b><small>Prazo ${fmt(d.due)} · registro manual</small><div style="margin-top:9px">${badge(d.status)} ${d.url?`<a class="link-btn" href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">Abrir link ↗</a>`:''}</div></div><button class="icon-btn" data-action="delivery:${p.id}:${d.id}" aria-label="Editar entrega">${icon('edit')}</button></div>`).join('')||empty('Da criação à entrega','Adicione fotos, filmes, reels ou álbuns.')}</div><p class="legend">Nesta versão, os links apontam para serviços externos. Aprovações e entregas são registradas manualmente.</p>`;
if(tab==='Financeiro')content=`<div class="card"><div class="between section-title"><h2>Lançamentos do trabalho</h2>${btn('Adicionar','project-transaction:'+p.id,'plus')}</div>${financeRows(p.id)}</div>`;
return `<button class="link-btn row" data-action="nav:projects">${icon('back')} Todos os trabalhos</button><div class="detail-cover section"><img src="${picture(p)}" alt=""><div class="grow"><div class="status-line">${badge(p.stage)}<small>${esc(p.type)}</small></div><h1 style="margin-top:12px">${esc(p.name)}</h1><small>${esc(c?.name)}</small></div></div><div class="tabs">${tabs.map(x=>`<button class="tab ${x===tab?'active':''}" data-action="tab:${x}">${x}</button>`).join('')}</div>${content}`}
function checkRows(p){return p.checks.map(c=>`<label class="check-row ${c.done?'done':''}"><input type="checkbox" data-check="${p.id}:${c.id}" ${c.done?'checked':''}><span class="grow">${esc(c.text)}</span><button type="button" class="icon-btn" data-action="remove-check:${p.id}:${c.id}" aria-label="Remover item">${icon('close')}</button></label>`).join('')||empty('Tudo pronto começa aqui','Adicione os itens que você precisa conferir.')}
function sessionPage(){const p=project(selected);if(!p)return '';return `<div class="session-mode"><div class="between section-title">${btn('Voltar ao trabalho','project:'+p.id,'back')}<span class="badge">MODO SESSÃO</span></div><section class="card"><p class="eyebrow" style="color:var(--accent)">EM CAMPO</p><h1>${esc(p.name)}</h1><p class="muted">${esc(client(p.clientId)?.name)} · ${fmt(p.date)}</p><div class="row wrap">${p.location?`<a class="btn" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.location)}" target="_blank" rel="noopener">${icon('pin')}${esc(p.location)}</a>`:''}${waButton(client(p.clientId),p)}</div></section><section class="card section"><div class="between section-title"><h2>Conferência da sessão</h2>${btn('Item','check:'+p.id,'plus')}</div>${checkRows(p)}</section><section class="card section"><div class="between section-title"><h2>Briefing à mão</h2>${btn('Editar','brief:'+p.id,'edit')}</div><p class="note">${esc(p.brief||'Nenhum briefing registrado.')}</p></section><p class="legend">Registros locais disponíveis neste navegador. Mapas e WhatsApp podem precisar de conexão.</p></div>`}
function waButton(c,p){let phone=(c?.phone||'').replace(/\D/g,'');if(phone.length<10||phone.length>15)return '';if(phone.length===10||phone.length===11)phone='55'+phone;return `<a class="btn" target="_blank" rel="noopener noreferrer" href="https://wa.me/${phone}?text=${encodeURIComponent('Olá, '+c.name+'! Vamos conversar sobre '+(p?.name||'seu próximo trabalho')+'?')}">${icon('phone')}WhatsApp</a>`}
function gearPage(){return header('Equipamentos','Seu kit pronto para a próxima história.',btn('Novo equipamento','new:gear','plus','primary'))+`<div class="banner"><div><p class="eyebrow">CUIDADO COM O SEU OLHAR</p><h2>Preparar também é criar.</h2><p>Acompanhe seu equipamento e registre o que precisa de atenção.</p></div><img src="${img.gear}" alt="Miniaturas trabalhando na manutenção de uma câmera"></div><div class="equipment-grid">${state.gear.map(g=>`<article class="card"><div class="between"><div class="gear-icon">${icon(g.category==='Áudio'?'video':'camera')}</div>${badge(g.status)}</div><h3>${esc(g.name)}</h3><p class="muted" style="font-size:.875rem">${esc(g.model||g.category)}</p><p class="note">${esc(g.notes||'Sem observações.')}</p>${btn('Ver equipamento','gear:'+g.id,'arrow')}</article>`).join('')||`<div class="card full">${empty('Monte seu kit','Cadastre câmeras, lentes, áudio e acessórios.','new:gear')}</div>`}</div>`}
function referencesPage(){return header('Referências','Um lugar para a atmosfera do seu estúdio.')+`<div class="banner"><div><p class="eyebrow">DIREÇÃO CRIATIVA</p><h2>Luz, textura e intenção.</h2><p>Suas imagens de referência. O briefing de cada trabalho guarda a direção de cada sessão.</p></div><img src="${img.photo}" alt="Câmera clássica sobre tecido"></div><div class="grid cols3 ref-grid">${[['magic','Uma atmosfera cinematográfica'],['photo','Fotografia com personalidade'],['video','Histórias em movimento'],['gear','O cuidado nos bastidores'],['film','Sequência e narrativa'],['frames','Mural de memórias'],['mural','Referência de composição']].map(([i,t])=>`<article class="card ref-card"><a href="${img[i]}" target="_blank" rel="noopener"><img src="${img[i]}" alt="${t}" loading="lazy"></a><h3>${t}</h3><small>${i==='mural'?'Referência enviada · marca d’água preservada':'Imagem fornecida para o projeto'}</small></article>`).join('')}</div>`}
function settingsPage(){return header('Seu estúdio','Identidade, proteção dos registros e preferências.')+`<div class="grid cols2"><section class="card"><div class="between section-title"><h2>Cadastro do fotógrafo</h2>${btn('Editar','profile','edit')}</div><div class="data-list">${state.profile.logo?'<img class="profile-logo" src="'+state.profile.logo+'" alt="Logo do fotógrafo">':''}<div><small>Estúdio</small><b>${esc(state.profile.name)}</b></div><div><small>Profissional</small><b>${esc(state.profile.owner||'Não informado')}</b></div><div><small>WhatsApp</small><b>${esc(state.profile.phone||'Não informado')}</b></div><div><small>E-mail</small><b>${esc(state.profile.email||'Não informado')}</b></div><div><small>Cidade</small><b>${esc(state.profile.city||'Não informada')}</b></div></div></section><section class="card"><div class="gear-icon">${icon('shield')}</div><h2>Proteja suas histórias</h2><p class="note">Seus dados estão neste navegador. Exporte uma cópia para guardar fora do dispositivo. Um arquivo exportado ainda precisa ter a restauração conferida.</p><div class="row wrap">${btn('Exportar backup','backup','download','primary')}${btn('Restaurar','restore','shield')}</div><p class="legend">${state.clients.length} clientes · ${state.projects.length} trabalhos · ${state.events.length} compromissos · ${state.transactions.length} lançamentos</p></section><section class="card"><h2>Senha local</h2><p class="note">${record?.encrypted?'Este espaço usa senha e criptografia local. Guarde sua senha: não há recuperação por e-mail.':'Você pode proteger este espaço com uma senha. Não há conta em nuvem nem recuperação por e-mail nesta versão.'}</p>${btn(record?.encrypted?'Alterar senha':'Criar senha','password','shield')}${record?.encrypted?btn('Bloquear','exit','logout'):''}</section><section class="card"><h2>Dados e transparência</h2><p class="note">${mode==='demo'?'Você está na demonstração. Alterações ficam separadas dos seus dados reais.':'Você está no seu espaço real. As alterações são salvas apenas neste dispositivo.'}</p><p class="note">${navigator.onLine?'Conexão disponível.':'Sem conexão no momento.'} Galerias, mapas e WhatsApp são serviços externos.</p>${btn('Sair do estúdio','exit','logout')}<p class="legend">LENS CORE STUDIO · V${VERSION}<br>Galerias online e portal do cliente: próximos ciclos.</p></section></div>`}
function morePage(){return header('Nos bastidores','Tudo o que mantém seu estúdio em movimento.')+`<div class="more-grid">${navs.slice(4).map(([r,t,i])=>`<button class="card more-card" data-action="nav:${r}">${icon(i)}<span class="grow">${t}</span>${icon('arrow')}</button>`).join('')}<button class="card more-card" data-action="exit">${icon('logout')}Sair</button></div>`}
function render(){if(!state){$('#app').innerHTML=welcome();return}let pages={home:homePage,projects:projectsPage,clients:clientsPage,agenda:agendaPage,project:projectPage,session:sessionPage,finance:financePage,gear:gearPage,quotes:quotesPage,contracts:contractsPage,settings:settingsPage,more:morePage};$('#app').innerHTML=shell((pages[route]||homePage)());}
function openForm(kind,id=null,pid=null){const p=pid?project(pid):null;let x={},body='',title='',opts=state.projects.map(x=>[x.id,x.name]);if(kind==='client'){x=client(id)||{};title=id?'Editar cliente':'Novo cliente';body=field('Nome / razão social','name',x.name,'text','required maxlength="120"')+select('Tipo','type',['Pessoa','Empresa'],x.type)+field('WhatsApp','phone',x.phone,'tel','placeholder="(11) 99999-9999"')+field('E-mail','email',x.email,'email')+select('Origem','source',['Indicação','Instagram','Site','WhatsApp','Outro'],x.source)+area('Observações','notes',x.notes)}
if(kind==='project'){if(!state.clients.length){toast('Cadastre o primeiro cliente para criar um trabalho.');return openForm('client')}x=project(id)||{};title=id?'Editar trabalho':'Novo trabalho';body=field('Nome do trabalho','name',x.name,'text','required maxlength="160"')+select('Cliente','clientId',state.clients.map(c=>[c.id,c.name]),x.clientId,'required')+select('Serviço','type',['Fotografia','Vídeo','Foto + Vídeo'],x.type)+select('Etapa','stage',stages,x.stage||'Consulta')+field('Data principal','date',x.date,'date')+field('Prazo geral','due',x.due,'date')+field('Valor total (R$)','value',x.value!=null?(x.value/100).toFixed(2):'','number','min="0" step="0.01" required')+field('Local','location',x.location)+area('Briefing','brief',x.brief)+area('Observações internas','notes',x.notes)+`<label class="full">Foto de capa (opcional)<input type="file" name="coverFile" accept="image/png,image/jpeg,image/webp"></label><div class="full">${x.cover?'<img class="cover-preview" src="'+x.cover+'" alt="Capa atual">':''}<label class="row"><input type="checkbox" name="removeCover" value="yes"> Remover capa atual</label></div>`}
if(kind==='event'){x=state.events.find(x=>x.id===id)||{};title=id?'Editar compromisso':'Novo compromisso';body=field('Título','title',x.title,'text','required maxlength="160"')+select('Trabalho','projectId',[['','Sem trabalho vinculado'],...opts],x.projectId||pid||'')+select('Tipo','type',['Sessão','Reunião','Edição','Entrega','Lembrete','Atividade','Manutenção','Outro'],x.type)+field('Local','location',x.location)+field('Início','start',x.start||chosen+'T09:00','datetime-local','required')+field('Fim','end',x.end||chosen+'T10:00','datetime-local','required')+area('Observações','notes',x.notes)}
if(kind==='transaction'){if(!state.projects.length){toast('Crie um trabalho antes de lançar valores.');return}x=state.transactions.find(x=>x.id===id)||{};title=id?'Editar lançamento':'Novo lançamento';body=select('Trabalho','projectId',opts,x.projectId||pid,'required')+select('Tipo','type',['Recebimento','Despesa','Estorno'],x.type)+field('Descrição','description',x.description,'text','required maxlength="160"')+field('Valor (R$)','amount',x.amount?(x.amount/100).toFixed(2):'','number','min="0.01" step="0.01" required')+field('Data','date',x.date||today(),'date','required')+'<p class="note full">Registre apenas movimentos efetivados. Um estorno reduz o recebido e aumenta o saldo a receber.</p>'}
if(kind==='gear'){x=state.gear.find(x=>x.id===id)||{};title=id?'Editar equipamento':'Novo equipamento';body=field('Nome','name',x.name,'text','required maxlength="120"')+select('Categoria','category',['Câmera','Lente','Áudio','Luz','Suporte','Acessório'],x.category)+field('Marca / modelo','model',x.model)+field('Número de série','serial',x.serial)+select('Situação','status',['Disponível','Em uso','Manutenção'],x.status)+area('Observações','notes',x.notes)}
body=`<input type="hidden" name="id" value="${id||''}"><div class="grid cols2 form-cols">${body}</div>`+(id&&kind!=='project'?`<div class="section">${btn('Excluir '+({client:'cliente',event:'compromisso',transaction:'lançamento',gear:'equipamento'}[kind]),'delete:'+kind+':'+id,'trash','danger')}</div>`:'');modal(title,body,kind)}
function cents(v){const n=Number(v);if(!Number.isFinite(n)||n<0||n>1e10)throw Error('Informe um valor válido.');return Math.round(n*100)}
async function enter(m){mode=m;key=null;revision=0;record=await readRecord();if(record?.encrypted){modal('Entrar no estúdio',`<p class="note">Informe a senha deste espaço local.</p><label>Senha<div class="password-wrap"><input type="password" name="password" required autocomplete="current-password">${btn('','eye','eye')}</div></label>`,'unlock','Entrar');return}state=record?validate(record.data):m==='demo'?demoData():blank();revision=record?.rev||0;if(!record)await commit(()=>{},'Espaço criado');go('home');if(m==='real'&&!state.profile.owner&&!state.projects.length)profileForm();}
function profileForm(){modal('Perfil do estúdio',`<div class="grid cols2 form-cols">${field('Nome do estúdio','name',state.profile.name,'text','required maxlength="100"')}${field('Seu nome','owner',state.profile.owner,'text','maxlength="100"')}${field('WhatsApp','phone',state.profile.phone,'tel')}${field('E-mail','email',state.profile.email,'email')}${field('Cidade','city',state.profile.city)}<label class="full">Logo do fotógrafo (opcional)<input type="file" name="logoFile" accept="image/png,image/jpeg,image/webp"></label><div class="full">${state.profile.logo?'<img class="profile-logo" src="'+state.profile.logo+'" alt="Logo atual">':''}<label class="row"><input type="checkbox" name="removeLogo" value="yes"> Remover logo atual</label><small>PNG, JPG ou WebP. Usado no cabeçalho dos PDFs.</small></div></div>`,'profile')}
async function submit(kind,f){const v=Object.fromEntries([...new FormData(f)].filter(([k])=>!['coverFile','logoFile'].includes(k)));const id=v.id||uid();if(kind==='unlock'){try{key=await derive(v.password,record.salt);state=await decode(record,key)}catch{key=null;throw Error('Senha incorreta ou dados danificados.')}revision=record.rev;closeModal(true);go('home');return}
if(kind==='password'){if(v.password.length<10)throw Error('Use pelo menos 10 caracteres.');if(v.password!==v.confirm)throw Error('As senhas não conferem.');const oldKey=key,oldRec=record;const salt=b64(crypto.getRandomValues(new Uint8Array(16)));key=await derive(v.password,salt);record={...record,salt};try{await commit(()=>{},'Senha local configurada')}catch(e){key=oldKey;record=oldRec;throw e}await new Promise((res,rej)=>{const tx=db.transaction('vault','readwrite');tx.objectStore('vault').delete(mode+'-before-restore');tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});closeModal(true);toast('Senha salva. Guarde-a em um local seguro.');return}
if(kind==='restore'){await restoreFile(f.file.files[0],v.password);closeModal(true);return}
if(kind==='profile'){await commit(d=>d.profile={...d.profile,personType:v.personType||'PF',document:v.document||'',cep:v.cep||'',street:v.street||'',number:v.number||'',complement:v.complement||'',district:v.district||'',uf:v.uf||'',name:v.name.trim(),owner:v.owner.trim(),phone:v.phone,email:v.email,city:v.city,logo:v.logo||''},'Perfil atualizado')}
if(kind==='brief'){await commit(d=>d.projects.find(p=>p.id===v.pid).brief=v.brief,'Briefing atualizado')}
if(kind==='check'){if(!v.text.trim())throw Error('Escreva o item.');await commit(d=>d.projects.find(p=>p.id===v.pid).checks.push({id:uid(),text:v.text.trim(),done:false}),'Item adicionado')}
if(kind==='delivery'){if(!validURL(v.url))throw Error('Use um endereço começando por https:// ou http://.');const item={id:v.did||uid(),name:v.name.trim(),due:v.due,status:v.status,url:v.url.trim()};await commit(d=>{const p=d.projects.find(p=>p.id===v.pid),i=p.deliveries.findIndex(x=>x.id===item.id);i<0?p.deliveries.push(item):p.deliveries.splice(i,1,item)},'Entrega atualizada')}
if(['client','project','event','transaction','gear'].includes(kind)){let obj={...(kind==='event'?state.events.find(e=>e.id===id):{}),...v,id};if(kind==='client'&&!v.name.trim())throw Error('Informe o nome.');if(kind==='project'){obj.value=cents(v.value);if(v.date&&v.due&&v.due<v.date)throw Error('O prazo geral deve ser igual ou posterior à data principal.');const old=project(v.id);obj.checks=old?.checks||[{id:uid(),text:'Conferir briefing e cronograma',done:false},{id:uid(),text:'Conferir baterias, cartões e equipamentos',done:false}];obj.deliveries=old?.deliveries||[];}
if(kind==='transaction'){obj.amount=cents(v.amount);if(obj.amount<=0)throw Error('O valor deve ser maior que zero.');if(v.type==='Estorno'){let available=state.transactions.filter(x=>x.projectId===v.projectId&&x.id!==id).reduce((s,x)=>s+(x.type==='Recebimento'?x.amount:x.type==='Estorno'?-x.amount:0),0);if(obj.amount>available)throw Error('O estorno não pode superar o recebido líquido.')}}
if(kind==='event'){if(!v.start||!v.end||new Date(v.end)<=new Date(v.start))throw Error('O fim deve ser posterior ao início.');const conflict=state.events.find(e=>e.id!==id&&new Date(v.start)<new Date(e.end)&&new Date(v.end)>new Date(e.start));if(conflict)throw Error('Conflito de horário com “'+conflict.title+'”. Ajuste o intervalo.');}
const collection={client:'clients',project:'projects',event:'events',transaction:'transactions',gear:'gear'}[kind];await commit(d=>{let i=d[collection].findIndex(x=>x.id===id);i<0?d[collection].push(obj):d[collection].splice(i,1,obj)},'Registro salvo: '+kind);if(kind==='project')go('project',id);}
closeModal(true);toast('Salvo no estúdio.');}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
async function backup(){const payload={format:'LumeBackup',version:1,exportedAt:new Date().toISOString(),source:mode,record:await encode(state)};download(`LUME-${mode}-${today()}.lumebak`,JSON.stringify(payload),'application/json');toast('Backup gerado. Confira o arquivo na pasta de downloads.');}
async function restoreFile(file,pass){if(!file)throw Error('Selecione um backup.');if(file.size>25000000)throw Error('Arquivo muito grande para esta versão.');let pack;try{pack=JSON.parse(await file.text())}catch{throw Error('Arquivo inválido.')}if(pack.format!=='LumeBackup'||pack.version!==1||!pack.record)throw Error('Backup incompatível.');let data;if(pack.record.encrypted){if(!pass)throw Error('Informe a senha usada neste backup.');try{const k=await derive(pass,pack.record.salt);data=await decode(pack.record,k)}catch{throw Error('Senha incorreta ou backup corrompido.')}}else data=validate(pack.record.data);if(pack.source!==mode)throw Error('Abra o espaço '+(pack.source==='demo'?'de demonstração':'real')+' para restaurar este backup.');if(!confirm(`Restaurar ${data.clients.length} clientes e ${data.projects.length} trabalhos? Os registros atuais serão substituídos. Uma cópia anterior ficará guardada neste navegador.`))return;await new Promise((res,rej)=>{const tx=db.transaction('vault','readwrite');tx.objectStore('vault').put(record,mode+'-before-restore');tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});await commit(d=>{for(const k of Object.keys(d))delete d[k];Object.assign(d,data)},'Backup restaurado');go('home');toast('Restauração concluída neste dispositivo.');}
function printQuote(pid){const p=project(pid),c=client(p.clientId),t=totals(pid),w=window.open('','_blank');if(!w){toast('Permita abrir uma nova janela para imprimir.');return}w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Proposta · ${esc(p.name)}</title><style>body{font:16px/1.7 Arial;color:#25302f;max-width:800px;margin:45px auto;padding:25px}header{border-bottom:3px solid #c99564;padding-bottom:24px}h1{font-family:Georgia;font-size:32px}small{color:#67716c}.box{background:#f6f2ec;padding:22px;margin:25px 0}pre{white-space:pre-wrap;font:inherit}button{padding:12px 22px;cursor:pointer}@media print{button{display:none}}</style></head><body><header><small>LENS CORE STUDIO · PROPOSTA DE SERVIÇO</small><h1>${esc(state.profile.name)}</h1>${esc(state.profile.owner)}<br>${esc(state.profile.email)} · ${esc(state.profile.phone)}</header><h2>${esc(p.name)}</h2><p><b>Cliente:</b> ${esc(c.name)}<br><b>Serviço:</b> ${esc(p.type)}<br><b>Data principal:</b> ${fmt(p.date)}<br><b>Local:</b> ${esc(p.location||'A definir')}<br><b>Prazo geral:</b> ${fmt(p.due)}</p><h3>Escopo e briefing</h3><pre>${esc(p.brief||'Escopo a definir com o cliente.')}</pre><h3>Entregáveis</h3>${p.deliveries.length?'<ul>'+p.deliveries.map(d=>`<li>${esc(d.name)} · ${fmt(d.due)}</li>`).join('')+'</ul>':'<p>A definir.</p>'}<div class="box"><b>Valor total: ${money(p.value)}</b></div><p><small>Documento de proposta gerado em ${fmt(today())}. Condições de pagamento e contratação devem ser acordadas entre as partes. Este documento não registra aceite nem assinatura.</small></p><button onclick="window.print()">Imprimir / salvar PDF</button></body></html>`);w.document.close();}
async function action(a){const [cmd,id,arg]=a.split(':');if(cmd==='close')return closeModal();if(cmd==='eye'){const input=$('#modal input[name=password]');input.type=input.type==='password'?'text':'password';return}if(cmd==='enter')return enter(id);if(cmd==='exit'){if(busy)return;state=null;key=null;route='home';closeModal(true);render();return}if(cmd==='nav')return go(id);if(cmd==='new')return openForm(id);if(cmd==='edit')return openForm(id,arg);if(cmd==='project')return go('project',id);if(cmd==='session')return go('session',id);if(cmd==='tab'){tab=id;render();return}if(cmd==='month'){const [y,m]=month.split('-').map(Number);month=localDate(new Date(y,m-1+Number(id),1)).slice(0,7);render();return}if(cmd==='today'){chosen=today();month=chosen.slice(0,7);render();return}if(cmd==='day'){chosen=id;render();return}if(cmd==='profile')return profileForm();if(cmd==='backup')return backup();if(cmd==='quote')return printQuote(id);if(cmd==='event'||cmd==='gear'||cmd==='transaction')return openForm(cmd,id);if(cmd==='project-event')return openForm('event',null,id);if(cmd==='project-transaction')return openForm('transaction',null,id);
if(cmd==='client'){const c=client(id);modal(c.name,`<div class="data-list"><div><small>Contato</small><b>${esc(c.phone||c.email||'Não informado')}</b></div><div><small>Observações</small><p class="note">${esc(c.notes||'Nenhuma observação.')}</p></div></div><div class="row wrap">${btn('Editar cliente','edit:client:'+id,'edit')}${waButton(c)}</div><h3 class="section">Trabalhos</h3>${state.projects.filter(p=>p.clientId===id).map(p=>`<button class="btn" data-action="open-client-project:${p.id}" style="width:100%;margin-bottom:10px">${esc(p.name)} ${icon('arrow')}</button>`).join('')||'<p class="note">Ainda sem trabalhos.</p>'}`);return}
if(cmd==='open-client-project'){closeModal(true);return go('project',id)}
if(cmd==='brief'){const p=project(id);modal('Briefing do trabalho',`<input type="hidden" name="pid" value="${id}">${area('Objetivo, estilo, roteiro e orientações','brief',p.brief)}`,'brief');return}
if(cmd==='check'){modal('Adicionar ao checklist',`<input type="hidden" name="pid" value="${id}">${field('O que precisa ser feito?','text','','text','required maxlength="240"')}`,'check');return}
if(cmd==='remove-check'){if(!confirm('Remover este item do checklist?'))return;await commit(d=>{const p=d.projects.find(p=>p.id===id);p.checks=p.checks.filter(c=>c.id!==arg)},'Item removido');return}
if(cmd==='delivery'){const p=project(id),d=p.deliveries.find(d=>d.id===arg)||{};modal(arg?'Editar entrega':'Nova entrega',`<input type="hidden" name="pid" value="${id}"><input type="hidden" name="did" value="${arg||''}"><div class="grid cols2 form-cols">${field('Entregável','name',d.name,'text','required maxlength="180"')}${field('Prazo','due',d.due||p.due,'date')}${select('Situação','status',['Pendente','Em produção','Aguardando aprovação','Entregue'],d.status)}${field('Link externo (opcional)','url',d.url,'url','placeholder="https://"')}</div><p class="legend">A situação é registrada manualmente pelo profissional.</p>${arg?btn('Remover entrega','remove-delivery:'+id+':'+arg,'trash','danger'):''}`,'delivery');return}
if(cmd==='remove-delivery'){if(!confirm('Remover este entregável?'))return;await commit(d=>{const p=d.projects.find(p=>p.id===id);p.deliveries=p.deliveries.filter(x=>x.id!==arg)},'Entrega removida');closeModal(true);return}
if(cmd==='duplicate'){if(!confirm('Criar uma nova consulta com o briefing e checklist? Datas, entregas, pagamentos e compromissos não serão copiados.'))return;const p=structuredClone(project(id));p.id=uid();p.name+=' (cópia)';p.stage='Consulta';p.date='';p.due='';p.deliveries=[];p.checks=p.checks.map(c=>({...c,id:uid(),done:false}));await commit(d=>d.projects.push(p),'Trabalho duplicado');go('project',p.id);toast('Cópia criada como consulta.');return}
if(cmd==='archive'){if(!confirm('Arquivar este trabalho? O histórico será preservado.'))return;await commit(d=>d.projects.find(p=>p.id===id).stage='Arquivado','Trabalho arquivado');return}
if(cmd==='delete-project'){const p=project(id);if(p.stage!=='Consulta'||state.transactions.some(x=>x.projectId===id)||state.events.some(x=>x.projectId===id)||p.deliveries.length)throw Error('Este trabalho possui histórico. Arquive-o para preservar os registros.');if(!confirm('Excluir este rascunho?'))return;await commit(d=>d.projects=d.projects.filter(p=>p.id!==id),'Rascunho excluído');go('projects');return}
if(cmd==='delete'){const collections={client:'clients',event:'events',transaction:'transactions',gear:'gear'},col=collections[id];if(!col)return;if(id==='client'&&state.projects.some(p=>p.clientId===arg))throw Error('Este cliente possui trabalhos vinculados e não pode ser excluído.');if(id==='transaction'){const t=state.transactions.find(t=>t.id===arg);if(t.type==='Recebimento'&&totals(t.projectId).paid-t.amount<0)throw Error('Este recebimento já possui estorno. Corrija os estornos primeiro.');}if(!confirm('Excluir este registro? Esta ação não pode ser desfeita.'))return;await commit(d=>d[col]=d[col].filter(x=>x.id!==arg),'Registro excluído: '+id);closeModal(true);toast('Registro excluído.');return}
if(cmd==='password'){modal(record?.encrypted?'Alterar senha local':'Criar senha local',`<p class="note">Use pelo menos 10 caracteres. Esta senha protege o espaço local com criptografia. Não há recuperação por e-mail; guarde-a com segurança.</p><label>Nova senha<div class="password-wrap"><input name="password" type="password" required minlength="10" autocomplete="new-password">${btn('','eye','eye')}</div></label><div style="margin-top:16px">${field('Confirmar senha','confirm','','password','required minlength="10" autocomplete="new-password"')}</div>`,'password','Salvar senha');return}
if(cmd==='restore'){modal('Validar e restaurar backup',`<p class="note">O backup substitui os registros deste espaço. Faça uma exportação antes de continuar. A senha abaixo só é necessária para arquivos criptografados.</p><label>Arquivo .lumebak<input type="file" name="file" accept=".lumebak,application/json" required></label><div style="margin-top:16px"><label>Senha do backup (se houver)<div class="password-wrap"><input type="password" name="password" autocomplete="off">${btn('','eye','eye')}</div></label></div>`,'restore','Validar e restaurar');return}
if(cmd==='csv'){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const rows=[['Data','Tipo','Trabalho','Descrição','Valor R$'],...state.transactions.map(t=>[t.date,t.type,project(t.projectId)?.name,t.description,(t.amount/100).toFixed(2).replace('.',',')])];download('LENSCORE-financeiro-'+today()+'.csv','\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Arquivo CSV gerado.');return}}
function reportError(e){const message=e?.message||'Não foi possível concluir. Tente novamente.';if($('#modal').open&&$('#form-error')){$('#form-error').textContent=message;$('#form-error').scrollIntoView?.({block:'nearest'});}else toast(message)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();Promise.resolve(action(el.dataset.action)).catch(reportError)});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button][data-action]')){e.preventDefault();Promise.resolve(action(e.target.dataset.action)).catch(reportError)}});
document.addEventListener('submit',async e=>{if(e.target.getAttribute('id')!=='form')return;e.preventDefault();const f=e.target,button=f.querySelector('[type=submit]');if(button.disabled)return;button.disabled=true;$('#form-error').textContent='';try{await submit(f.dataset.kind,f)}catch(err){reportError(err)}finally{if(button.isConnected)button.disabled=false}});
document.addEventListener('input',e=>{if(e.target.closest('#form'))dirty=true;if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render();const x=$('#search');x.focus();x.setSelectionRange(pos,pos)}});
document.addEventListener('change',async e=>{try{if(e.target.id==='filter'){filter=e.target.value;render()}if(e.target.id==='month'&&e.target.value){month=e.target.value;render()}if(e.target.id==='stage'){const value=e.target.value;await commit(d=>d.projects.find(p=>p.id===selected).stage=value,'Etapa alterada')}if(e.target.dataset.check){const [pid,cid]=e.target.dataset.check.split(':'),value=e.target.checked;await commit(d=>d.projects.find(p=>p.id===pid).checks.find(c=>c.id===cid).done=value,'Checklist atualizado')}}catch(err){render();reportError(err)}});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal()});
window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue=''}});
window.addEventListener('online',()=>{if(state&&route==='settings')render()});window.addEventListener('offline',()=>{if(state&&route==='settings')render()});
async function boot(){try{db=await openDB();render();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});const mc=document.modelContext;if(mc?.registerTool){for(const t of [{name:'lume_list_projects',title:'Listar trabalhos',description:'Lê os trabalhos do espaço aberto no LENS CORE STUDIO.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||Object.keys(input).length)throw Error('Nenhum parâmetro é aceito.');if(!state)throw Error('Abra seu estúdio primeiro.');return {projects:state.projects.map(p=>({id:p.id,name:p.name,stage:p.stage,due:p.due}))}}},{name:'lume_open_project',title:'Abrir trabalho',description:'Navega para um trabalho existente; não altera registros.',inputSchema:{type:'object',properties:{projectId:{type:'string'}},required:['projectId'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:async input=>{if(!input||Object.keys(input).length!==1||typeof input.projectId!=='string'||!state||!project(input.projectId))throw Error('Trabalho não encontrado.');go('project',input.projectId);return {opened:input.projectId}}}])try{await mc.registerTool(t)}catch{}}}catch(e){$('#app').innerHTML=`<div class="boot">LUME<span>Não foi possível abrir o armazenamento deste navegador.</span><span>Verifique as permissões de armazenamento e tente novamente.</span></div>`}}

